/**
 * DIGIT HR round 2 (owner brief 2026-11-15 13:01, ruling 1): every DIGIT document the definition proposes (sheet 04
 * entities, data-model changes) plus the documents the 60 round-2 features need, as additive DIGIT DocTypes. One compact
 * line per DocType, expanded by ./doctypes.ts into the DocType JSON, the Before Save rules (client: interpreted by
 * expr.ts; server: the same rule as a Python Server Script), the approval workflow, the section placement, the Arabic
 * labels and the bilingual print, so the preview and the Frappe export never drift. Native HRMS documents are never
 * duplicated: entities the native app already has (Job Requisition, Travel Request, Help Article) or the HR app already
 * owns (DIGIT HR Service Case, DIGIT Service Catalog Item, DIGIT Saudi Rule Set) are listed in NATIVE_EQUIVALENT instead.
 *
 * Field grammar `name[*][:Type][>Target][=A,B][~عربي]`: * required, Type (Data by default; Table/Table MultiSelect take a
 * child DocType after >), > Link target, = Select options (first = default), ~ Arabic label (English label = title-cased
 * fieldname). Macros: @emp (employee + name + company, required), @empo (optional employee), @co (company, required),
 * @dept, @br, @period (from/to date, required), @notes. `--Title~عنوان` starts a section, `||` a column.
 */
export interface EntitySpec {
  name: string; section: string; ar: string; title?: string; fields: string;
  /** cond | English message | Arabic message (Before Save; cond uses the expr.ts grammar over doc fields). */
  rules?: [string, string, string][];
  child?: boolean; submit?: boolean; print?: boolean;
  /** approval workflow on approval_status (Draft → Pending Approval → Approved / Rejected); approver ≠ requester when four. */
  wf?: boolean; four?: boolean;
  /** the definition entity / feature this document answers (for the developer guide and the result file). */
  src: string;
}

